using Godot;
using System;
using System.Linq;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
 HFlowContainer directiveCancelRetryBar=null!;OptionButton cancellationOriginalChoice=null!;EntityId[] cancellationOriginalIds=[];string? selectedCancellationOriginal;
 void BuildDirectiveCancelRetryUI(VBoxContainer root){directiveCancelRetryBar=new();root.AddChild(directiveCancelRetryBar);directiveCancelRetryBar.AddChild(new Label{Text="対象の取消原本"});cancellationOriginalChoice=new(){CustomMinimumSize=new(350,0)};directiveCancelRetryBar.AddChild(cancellationOriginalChoice);cancellationOriginalChoice.ItemSelected+=n=>{selectedCancellationOriginal=cancellationOriginalIds[(int)n].Value;Refresh();};Add(directiveCancelRetryBar,"unit-directive-cancel-retry","選んだ取消原本を再送",RetrySelectedCancellation);buttons["unit-directive-cancel-retry"].TooltipText="この取消原本の不達報告を受け取り、同じ隊の所在地を確認したときに再送できます。取消対象・指定時刻・元期限を維持します。";}
 void RefreshDirectiveCancelRetry(){if(directiveCancelRetryBar==null)return;var w=Snapshot();EntityId[] ids=selectedDirectiveOriginal==null?[]:NewGameMilitary.CancellationOriginalsFor(w,new(selectedDirectiveOriginal));directiveCancelRetryBar.Visible=directiveRetryBar.Visible&&ids.Length>0;if(!ids.SequenceEqual(cancellationOriginalIds)){cancellationOriginalChoice.Clear();cancellationOriginalIds=ids;foreach(var id in ids){var q=w.NewMilitary!.Requests.Single(q=>q.Input.Id==id);cancellationOriginalChoice.AddItem("取消／開始"+q.At+"秒／指定時刻"+q.Input.DirectiveCancellation!.EffectiveAt+"秒"+(q.Input.DeliverBy is {} until?"／期限"+until+"秒":""));}}if(selectedCancellationOriginal==null||!ids.Any(id=>id.Value==selectedCancellationOriginal))selectedCancellationOriginal=ids.LastOrDefault().Value;int index=Array.FindIndex(ids,id=>id.Value==selectedCancellationOriginal);if(index>=0)cancellationOriginalChoice.Select(index);buttons["unit-directive-cancel-retry"].Disabled=index<0||!NewGameMilitary.UnitDirectiveCancelRetryAllowed(w,ids[index]);if(index>=0)directiveCancelResult.Text=NewGameMilitary.UnitDirectiveCancellationOriginalStatus(w,ids[index]);}
 void RetrySelectedCancellation(){if(selectedCancellationOriginal==null)return;var w=Snapshot();var d=w.NewMilitary!.UnitDirective!.Cancellation!.Dispatches.SingleOrDefault(d=>d.Id.Value==selectedCancellationOriginal);if(d==null)return;var known=NewGameMilitary.SelectKnownTarget(w,d.Recipient);if(known==null)return;Submit(Session.DecideNewMilitary(new NewMilitaryInput(new("request:unit-directive-cancel-retry-ui/"+Session.Revision),NewMilitaryAction.RetryUnitDirectiveCancellation){DirectiveCancelRetry=new(NewGameMilitary.UnitDirectiveCancelRetryContract,d.Id,known),TransportPolicy=NewGameMilitary.UnitSenderEvidenceContract},Session.PlayerControl,Session.Revision));}
 object? DirectiveCancelRetryPose()=>directiveCancelRetryBar==null?null:new{Selected=selectedCancellationOriginal,Choices=cancellationOriginalIds,directiveCancelRetryBar.Visible,Enabled=!buttons["unit-directive-cancel-retry"].Disabled,Text=cancellationOriginalChoice.Selected>=0?cancellationOriginalChoice.GetItemText(cancellationOriginalChoice.Selected):""};
 internal string? SelectedCancellationOriginalId=>selectedCancellationOriginal;
 internal void SelectCancellationOriginal(EntityId id){Refresh();int index=Array.IndexOf(cancellationOriginalIds,id);if(index<0)throw new InvalidOperationException("未発送または別の指示に属する取消は選択できません");cancellationOriginalChoice.Select(index);cancellationOriginalChoice.EmitSignal(OptionButton.SignalName.ItemSelected,index);}
}
